Q: Google Maps JS combining boundaries and circles A: <ol>
<li><p>create the map the &quot;normal&quot; way:</p>
<pre><code>map = new google.maps.Map(document.getElementById(&quot;map&quot;), {
 center: myLatLng,
 zoom: 12,
 mapId: '8b37d7206ccf0121d4414bb0',
 });
</code></pre>
</li>
<li><p>add your circle:</p>
<pre><code>const cityCircle = new google.maps.Circle({
 strokeColor: &quot;#FF0000&quot;,
 strokeOpacity: 0.8,
 strokeWeight: 2,
 fillColor: &quot;#FF0000&quot;,
 fillOpacity: 0.35,
 map: map,
 center: myLatLng,
 radius: 3500,
});
</code></pre>
</li>
<li><p>style the border:</p>
<pre><code>featureLayer = map.getFeatureLayer(google.maps.FeatureType.LOCALITY);
 // Add a feature layer for localities.

 const featureStyleOptions = {
   strokeColor: '#810FCB',
   strokeOpacity: 1.0,
   strokeWeight: 3.0,
   fillColor: '#810FCB',
   fillOpacity: 0.5,
 };

 featureLayer.style = (options) =&gt; {
   if (options.feature.placeId == 'ChIJ0zQtYiWsVHkRk8lRoB1RNPo') {
     return featureStyleOptions;
   }
 };
</code></pre>
</li>
</ol>
<p><a href="https://jsfiddle.net/geocodezip/ycLh6n3f/3/" rel="nofollow noreferrer">proof of concept fiddle</a></p>
<p><a href="https://i.sstatic.net/it0zyvqj.png" rel="nofollow noreferrer"><img src="https://i.sstatic.net/it0zyvqj.png" alt="screenshot of resulting map" /></a></p>
<p><strong>code snippet</strong> (doesn't work, but is the same code as the working fiddle above)</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>let featureLayer;
let map;
async function initMap() {
  (await google.maps.importLibrary('maps'));
  const mapElement = document.querySelector('gmp-map');
  const myLatLng = {
    lat: 20.773,
    lng: -156.01
  };
  map = new google.maps.Map(document.getElementById("map"), {
    center: myLatLng,
    zoom: 12,
    mapId: '8b37d7206ccf0121d4414bb0',
  });
  const cityCircle = new google.maps.Circle({
    strokeColor: "#FF0000",
    strokeOpacity: 0.8,
    strokeWeight: 2,
    fillColor: "#FF0000",
    fillOpacity: 0.35,
    map: map,
    center: myLatLng,
    radius: 3500,
  });

  featureLayer = map.getFeatureLayer(google.maps.FeatureType.LOCALITY);
  // Add a feature layer for localities.

  const featureStyleOptions = {
    strokeColor: '#810FCB',
    strokeOpacity: 1.0,
    strokeWeight: 3.0,
    fillColor: '#810FCB',
    fillOpacity: 0.5,
  };

  featureLayer.style = (options) =&gt; {
    if (options.feature.placeId == 'ChIJ0zQtYiWsVHkRk8lRoB1RNPo') {
      return featureStyleOptions;
    }
  };

}</code></pre>
